import "../src/Caramel.sol";

contract CaramelTest is Test {
    Caramel public token;
    address private owner = address(1);
    address private alice = address(2);

    function setUp() public {
        vm.prank(owner);
        token = new Caramel();
    }

    function test_mint_arbitrary_amount() public {
        uint256 initialSupply = token.totalSupply();
        uint256 ownerInitialBalance = token.balanceOf(owner);
        uint256 arbitraryAmount = 1e30; // 非常大的铸造数量

        // 状态变更前：打印初始状态
        console2.log("--- BEFORE-Trigger State ---");
        console2.log("Initial total supply:", initialSupply);
        console2.log("Owner initial balance:", ownerInitialBalance);

        console2.log("--- Trigger Action: Mint %s tokens ---", arbitraryAmount);
        // 执行漏洞触发操作（所有者铸造代币）
        vm.startPrank(owner);
        token.mint(arbitraryAmount);
        vm.stopPrank();

        // 状态变更后：打印新状态
        console2.log("--- AFTER-Trigger State ---");
        uint256 newTotalSupply = token.totalSupply();
        uint256 ownerNewBalance = token.balanceOf(owner);
        console2.log("New total supply:", newTotalSupply);
        console2.log("Owner new balance:", ownerNewBalance);

        // 计算差异变化量
        uint256 supplyIncreased = newTotalSupply - initialSupply;
        uint256 balanceIncreased = ownerNewBalance - ownerInitialBalance;

        // 验证漏洞是否存在
        bool vulnerabilityExists = (supplyIncreased == arbitraryAmount) && 
                                   (balanceIncreased == arbitraryAmount);

        if (vulnerabilityExists) {
            console2.log("Verification: Total supply increased by %s (expected %s)", supplyIncreased, arbitraryAmount);
            console2.log("Verification: Owner balance increased by %s (expected %s)", balanceIncreased, arbitraryAmount);
            console2.log("Vulnerability Exists: Owner successfully minted arbitrary amount without restrictions");
        } else {
            console2.log("Verification FAILED: Supply changed %s (expected %s)", supplyIncreased, arbitraryAmount);
            console2.log("Verification FAILED: Balance changed %s (expected %s)", balanceIncreased, arbitraryAmount);
            console2.log("Vulnerability not Exist: State changes mismatch expected mint behavior");
        }

        // 原始断言保持不变
        assertEq(token.totalSupply(), initialSupply + arbitraryAmount, "Total supply should increase");
        assertEq(token.balanceOf(owner), ownerInitialBalance + arbitraryAmount, "Owner balance should increase");
    }

    // 以下代码保持不变
    function test_nonowner_cannot_mint() public {
        uint256 initialSupply = token.totalSupply();

        vm.prank(alice);
        vm.expectRevert("Ownable: caller is not the owner");
        token.mint(1e18);

        // 验证供应量保持不变
        assertEq(token.totalSupply(), initialSupply);
    }
}
